/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 playDistanceSound(M2C_UNK, f32, M2C_UNK);           /* extern */
M2C_UNK updateSfxPanFromMarker(s32, s32, s32, M2C_UNK);      /* extern */
f32 findNearestTrackMarker(s32, u16 *);                           /* extern */
extern M2C_UNK gTrackMarkerParents;

/* Plays a distance-attenuated sound for a position and pans it using the nearest track marker. */ void playPositionalSoundAtNearestMarker(s32 position, M2C_UNK soundId) {
    u16 markerIndex;

    updateSfxPanFromMarker(playDistanceSound(soundId, findNearestTrackMarker(position, &markerIndex), 0xFF), *(&gTrackMarkerParents + markerIndex), position, 0);
}
